def investigate(context, acquire):
    hist = acquire("history")
    # Family: put is one of IGNORE, REPLACE, UPSERT(value).
    # channel is one of: main changes(), main total_changes, main+other total_changes.
    # instrumentation: none or one AFTER INSERT trigger adding one log row.
    # We must find which combos are consistent with all receipts, then check
    # whether all consistent combos agree on the goal for the query sequence.

    def simulate(put_mode, chan_mode, trig):
        # returns (channel, committed_count, committed_sum) for context actions
        # state: dict key->value committed; pending per connection
        committed = {}
        # per-connection transaction state
        tx = {"main": None, "other": None}
        # total_changes per connection (counts direct row changes incl trigger?)
        # SQLite total_changes counts rows changed by INSERT/UPDATE/DELETE
        # statements, including changes made by triggers.
        total = {"main": 0, "other": 0}
        # changes() is last statement's direct changes on that connection
        last_changes = {"main": 0, "other": 0}
        # channel accumulation: for changes() mode, channel is the value of
        # changes() at end? Actually observed channel is emitted number.
        # We model channel as the counter value at end of sequence.
        # For changes() mode: channel = last_changes[main] at end.
        # For total_changes: channel = total[main] at end.
        # For total_changes+other: channel = total[main]+total[other] at end.

        def apply_write(conn, key, value, is_put):
            # returns number of direct row changes (0 or 1) for the statement
            # plus trigger changes added to total.
            nonlocal committed
            # determine current visible value for this connection
            # pending state: if tx open, use pending dict
            if tx[conn] is not None:
                view = tx[conn]
            else:
                view = committed
            direct = 0
            if is_put:
                if key in view:
                    if put_mode == "ignore":
                        direct = 0
                    elif put_mode == "replace":
                        view[key] = value
                        direct = 1
                    else:  # upsert
                        view[key] = value
                        direct = 1
                else:
                    view[key] = value
                    direct = 1
            else:  # update
                if key in view:
                    view[key] = value
                    direct = 1
                else:
                    direct = 0
            # trigger: AFTER INSERT fires only on actual insert (direct insert)
            # For put: insert happens when key not present (all modes) or
            # replace/upsert on existing (replace deletes+inserts, upsert updates).
            # AFTER INSERT trigger fires on INSERT statement rows.
            trig_changes = 0
            if trig and is_put:
                # insert occurred if direct==1 and it was an insert
                if put_mode == "ignore":
                    if direct == 1:
                        trig_changes = 1
                elif put_mode == "replace":
                    # REPLACE always inserts (delete+insert) when key exists too
                    if direct == 1:
                        trig_changes = 1
                else:  # upsert: insert only when key absent
                    if direct == 1 and key not in view_before:
                        trig_changes = 1
            return direct, trig_changes

        # We need view_before for upsert trigger. Simplify: track separately.
        # Reimplement more carefully.
        def do_write(conn, key, value, is_put):
            nonlocal committed
            if tx[conn] is not None:
                view = tx[conn]
            else:
                view = committed
            existed = key in view
            direct = 0
            inserted = False
            if is_put:
                if existed:
                    if put_mode == "ignore":
                        direct = 0
                    elif put_mode == "replace":
                        view[key] = value
                        direct = 1
                        inserted = True  # REPLACE does delete+insert
                    else:
                        view[key] = value
                        direct = 1
                        inserted = False
                else:
                    view[key] = value
                    direct = 1
                    inserted = True
            else:
                if existed:
                    view[key] = value
                    direct = 1
                else:
                    direct = 0
            trig_changes = 0
            if trig and inserted:
                trig_changes = 1
            last_changes[conn] = direct
            total[conn] += direct + trig_changes
            return direct

        for act in context["actions"]:
            op = act.get("op")
            conn = act.get("connection", "main")
            if op == "put":
                do_write(conn, act["key"], act["value"], True)
            elif op == "update":
                do_write(conn, act["key"], act["value"], False)
            elif op == "delete":
                if tx[conn] is not None:
                    view = tx[conn]
                else:
                    view = committed
                if act["key"] in view:
                    del view[act["key"]]
                    last_changes[conn] = 1
                    total[conn] += 1
                else:
                    last_changes[conn] = 0
            elif op == "begin":
                if tx[conn] is None:
                    tx[conn] = dict(committed)
            elif op == "commit":
                if tx[conn] is not None:
                    committed = tx[conn]
                    tx[conn] = None
            elif op == "rollback":
                if tx[conn] is not None:
                    tx[conn] = None

        if chan_mode == "changes":
            channel = last_changes["main"]
        elif chan_mode == "total":
            channel = total["main"]
        else:
            channel = total["main"] + total["other"]
        return channel, len(committed), sum(committed.values())

    put_modes = ["ignore", "replace", "upsert"]
    chan_modes = ["changes", "total", "both"]
    trigs = [False, True]

    consistent = []
    for pm in put_modes:
        for cm in chan_modes:
            for tg in trigs:
                ok = True
                for rec in hist:
                    acts = rec["actions"]
                    obs = rec["observed"]
                    # simulate with these actions
                    sub = {"actions": acts}
                    ch, cc, cs = simulate(pm, cm, tg)
                    if ch != obs["channel"] or cc != obs["committed_count"] or cs != obs["committed_sum"]:
                        ok = False
                        break
                if ok:
                    consistent.append((pm, cm, tg))

    if not consistent:
        return {"value": None, "unresolved": True}

    goal = context["goal"]
    vals = set()
    for pm, cm, tg in consistent:
        ch, cc, cs = simulate(pm, cm, tg)
        if goal == "channel":
            vals.add(ch)
        elif goal == "committed_count":
            vals.add(cc)
        else:
            vals.add(cs)
    if len(vals) == 1:
        return {"value": vals.pop(), "unresolved": False}
    return {"value": None, "unresolved": True}

